import { BrowserRouter, Routes, Route } from "react-router-dom";

// Context Providers
import { AuthProvider }  from "./context/AuthContext";
import { CartProvider }  from "./context/CartContext";

// Layout
import Navbar       from "./components/Navbar";
import Footer       from "./components/Footer";

// Public Pages
import Home         from "./pages/Home";
import Gallery      from "./pages/Gallery";
import Collections  from "./pages/Collections";
import About        from "./pages/About";
import ProductDetail from "./pages/ProductDetail";
import Login        from "./pages/Login";
import Register     from "./pages/Register";

// Protected Pages (must be logged in)
import Cart         from "./pages/Cart";
import Checkout     from "./pages/Checkout";
import OrderSuccess from "./pages/OrderSuccess";
import Profile      from "./pages/Profile";

// Admin Pages (must be logged in AND role === "admin")
import AdminLayout  from "./pages/AdminLayout";

// Route Guards
import { ProtectedRoute, AdminRoute } from "./components/ProtectedRoute";

function App() {
  return (
    // BrowserRouter gives all child components access to React Router
    <BrowserRouter>
      {/*
        AuthProvider must wrap CartProvider because CartProvider
        reads `token` from useAuth() to make authenticated API calls.
      */}
      <AuthProvider>
        <CartProvider>
          {/* Navbar is always visible */}
          <Navbar />

          <Routes>
            {/* ── Public Routes ─────────────────────────── */}
            <Route path="/"            element={<Home />} />
            <Route path="/gallery"     element={<Gallery />} />
            <Route path="/collections" element={<Collections />} />
            <Route path="/about"       element={<About />} />
            <Route path="/product/:id" element={<ProductDetail />} />
            <Route path="/login"       element={<Login />} />
            <Route path="/register"    element={<Register />} />

            {/* ── Protected Routes (login required) ─────── */}
            <Route element={<ProtectedRoute />}>
              <Route path="/cart"          element={<Cart />} />
              <Route path="/checkout"      element={<Checkout />} />
              <Route path="/order-success" element={<OrderSuccess />} />
              <Route path="/profile"       element={<Profile />} />
            </Route>

            {/* ── Admin Routes (admin role required) ─────── */}
            <Route element={<AdminRoute />}>
              <Route path="/admin" element={<AdminLayout />} />
            </Route>

            {/* ── 404 Fallback ───────────────────────────── */}
            <Route path="*" element={
              <div className="container text-center py-5">
                <h2 className="serif mb-2">404 — Page Not Found</h2>
                <p className="text-muted mb-4">The page you're looking for doesn't exist.</p>
                <a href="/" className="btn-af">Go Home</a>
              </div>
            } />
          </Routes>

          {/* Footer is always visible */}
          <Footer />
        </CartProvider>
      </AuthProvider>
    </BrowserRouter>
  );
}

export default App;
